), updated AS (
    UPDATE pets.ingredients AS ingredient
    SET category = source.category,
        subtype = source.subtype,
        portion = source.portion,
        calories = source.calories,
        protein = source.protein,
        fat = source.fat,
        carbs = source.carbs,
        moisture = source.moisture,
        fiber = source.fiber,
        ash = source.ash,
        cholesterol = source.cholesterol,
        sugar = source.sugar,
        calcium = source.calcium,
        phosphorus = source.phosphorus,
        magnesium = source.magnesium,
        sodium = source.sodium,
        potassium = source.potassium,
        iron = source.iron,
        copper = source.copper,
        zinc = source.zinc,
        manganese = source.manganese,
        linoleic = source.linoleic,
        alpha_linolenic = source.alpha_linolenic,
        arachidonic = source.arachidonic,
        epa = source.epa,
        dha = source.dha,
        choline = source.choline,
        selenium = source.selenium,
        iodine = source.iodine,
        vitamin_a = source.vitamin_a,
        vitamin_e = source.vitamin_e,
        vitamin_d = source.vitamin_d,
        vitamin_b1 = source.vitamin_b1,
        vitamin_b2 = source.vitamin_b2,
        vitamin_b3 = source.vitamin_b3,
        vitamin_b5 = source.vitamin_b5,
        vitamin_b6 = source.vitamin_b6,
        vitamin_b9 = source.vitamin_b9,
        vitamin_b12 = source.vitamin_b12,
        vitamin_c = source.vitamin_c,
        vitamin_k = source.vitamin_k,
        alpha_carotene = source.alpha_carotene,
        beta_carotene = source.beta_carotene,
        beta_cryptoxanthin = source.beta_cryptoxanthin,
        lutein_zeaxanthin = source.lutein_zeaxanthin,
        lycopene = source.lycopene,
        retinol = source.retinol,
        updated_at = now()
    FROM source
    WHERE lower(ingredient.name) = lower(source.name)
      AND (
          lower(coalesce(ingredient.subtype, '')) = lower(source.subtype)
          OR (ingredient.subtype IS NULL AND lower(source.subtype) = 'обыкновенный')
      )
    RETURNING lower(source.name) AS name_key, lower(source.subtype) AS subtype_key
)
INSERT INTO pets.ingredients (category, name, subtype, portion, calories, protein, fat, carbs, moisture, fiber, ash, cholesterol, sugar, calcium, phosphorus, magnesium, sodium, potassium, iron, copper, zinc, manganese, linoleic, alpha_linolenic, arachidonic, epa, dha, choline, selenium, iodine, vitamin_a, vitamin_e, vitamin_d, vitamin_b1, vitamin_b2, vitamin_b3, vitamin_b5, vitamin_b6, vitamin_b9, vitamin_b12, vitamin_c, vitamin_k, alpha_carotene, beta_carotene, beta_cryptoxanthin, lutein_zeaxanthin, lycopene, retinol)
SELECT category, name, subtype, portion, calories, protein, fat, carbs, moisture, fiber, ash, cholesterol, sugar, calcium, phosphorus, magnesium, sodium, potassium, iron, copper, zinc, manganese, linoleic, alpha_linolenic, arachidonic, epa, dha, choline, selenium, iodine, vitamin_a, vitamin_e, vitamin_d, vitamin_b1, vitamin_b2, vitamin_b3, vitamin_b5, vitamin_b6, vitamin_b9, vitamin_b12, vitamin_c, vitamin_k, alpha_carotene, beta_carotene, beta_cryptoxanthin, lutein_zeaxanthin, lycopene, retinol
FROM source
WHERE NOT EXISTS (
    SELECT 1
    FROM pets.ingredients AS ingredient
    WHERE lower(ingredient.name) = lower(source.name)
      AND lower(coalesce(ingredient.subtype, '')) = lower(source.subtype)
)
AND NOT EXISTS (
    SELECT 1
    FROM updated
    WHERE updated.name_key = lower(source.name)
      AND updated.subtype_key = lower(source.subtype)
);
